import numpy as np,mw_tool,mujoco,json
from pathlib import Path
s=mw_tool.Session()
def trial(force_target=5,gain=.001,down=.02,k=20,damp=.04,limit=.6,approach=25,ay=.74,az=.082):
 s.reset();peak=0;sumforce=0;touched=0;lo=0
 def force():
  f=0
  for i in range(s.data.ncon):
   if 37 in s.data.contact[i].geom:
    fc=np.zeros(6);mujoco.mj_contactForce(s.model,s.data,i,fc);f+=fc[0]
  return f
 def step(a):
  nonlocal peak,sumforce,touched
  s.step(a);f=force();peak=max(peak,f)
  if f>0:sumforce+=f;touched+=1
 def move(p,g,n,sp):
  for _ in range(n):step(np.r_[np.clip(100*(np.array(p)-s.data.mocap_pos[0]),-sp,sp),g])
 move([0,ay,az],1,approach,1.)
 for i in range(80):
  f=force()
  if f>force_target*.7:break
  step([0,0,-down,1])
 startforce=force()
 for i in range(250):
  f=force()
  err=s.target_pos[:2]-s.state()['object_pos'][:2];vel=s.data.qvel[9:11].copy()
  z=np.clip(gain*(f-force_target),-.1,.1)
  step(np.r_[np.clip(k*(err-damp*vel),-limit,limit),z,1])
  if np.linalg.norm(err)<.0002 and np.linalg.norm(vel)<.001:break
 end=s.data.mocap_pos[0].copy();end[2]=.20
 move(end,1,25,.8);move(end,-1,20,1.)
 st=s.state()
 return {'force_target':force_target,'gain':gain,'down':down,'k':k,'damp':damp,'limit':limit,'approach':approach,'ay':ay,'az':az,'distance':st['obj_to_target'],'steps':len(s.actions),'peak_force':peak,'mean_touch_force':sumforce/max(1,touched),'startforce':startforce,'success':st['success'],'obj':st['object_pos'].tolist()}
